import { afterAll, describe, expect, it } from "bun:test";
import type { ChildProcess } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

import { escapeCmdArgument, escapeCmdCommand } from "@kone/agent-core/windowsLaunch.js";

import type { CommitCliExecFile, CommitCliExecOptions } from "./textGen.js";
import { tryGenerateWithCli } from "./textGen.js";

// AI commit messages are generated by shelling out to whichever CLI the user
// has: codex, claude, then opencode, prompt as an argument. On Windows an npm
// install is a `.cmd` shim, so the call has to go through cmd.exe — and a
// candidate that cannot be launched is skipped for the next one, exactly like a
// spawn failure. Off Windows the execFile call has to stay byte-for-byte what it
// was, so both sides are asserted with literal arguments.

const root = fs.mkdtempSync(path.join(os.tmpdir(), "kone-textgen-win-"));

afterAll(() => {
  fs.rmSync(root, { recursive: true, force: true });
});

/** One recorded execFile call. */
type Recorded = {
  file: string;
  args: readonly string[];
  options: CommitCliExecOptions;
};

/** The environment a Windows machine presents for one install directory. */
function windowsEnv(binDir: string): NodeJS.ProcessEnv {
  return {
    PATH: binDir,
    PATHEXT: ".COM;.EXE;.BAT;.CMD;.PS1",
    ComSpec: "C:\\Windows\\System32\\cmd.exe",
  };
}

/** npm's install of one CLI in `dir`: the extensionless sh shim, the `.cmd`
 *  Windows starts, and the `.ps1` it cannot. */
function installNpmSiblings(dir: string, name: string): void {
  fs.mkdirSync(dir, { recursive: true });
  for (const [suffix, contents, mode] of [
    ["", "#!/bin/sh\n", 0o644],
    [".cmd", "@echo off\r\n", 0o644],
    [".ps1", "# not launchable\n", 0o644],
  ] as const) {
    const target = path.join(dir, `${name}${suffix}`);
    fs.writeFileSync(target, contents);
    fs.chmodSync(target, mode);
  }
}

/** A commit message a CLI could have answered with. */
const CLI_RESULT = '{"subject":"Add Windows launch","body":""}';

/** An execFile stand-in that records the launch and answers as the CLI would.
 *  The child is never touched: an immediately settled `done` clears the
 *  tree-kill timer before it can fire. */
function recordingExecFile() {
  const calls: Recorded[] = [];
  const execFile: CommitCliExecFile = (file, args, options) => {
    calls.push({ file, args, options });
    // SAFETY: the production path only reads `pid`, and only when a launch
    // outlives the timeout — this one answers at once.
    const child = { pid: 4321 } as ChildProcess;
    return { child, done: Promise.resolve({ stdout: CLI_RESULT }) };
  };
  return { execFile, calls };
}

/** The cmd.exe wrapper argv for one batch target and its argv. */
function expectedCmdArgs(file: string, args: readonly string[]): string[] {
  const line = [escapeCmdCommand(file), ...args.map((arg) => escapeCmdArgument(arg, true))].join(" ");
  return ["/d", "/s", "/c", `"${line}"`];
}

/** tryGenerateWithCli's codex candidate, restated literally. */
const PROMPT = "Write a commit message for the staged changes";
const CODEX_ARGS = [
  "exec",
  "--ephemeral",
  "--skip-git-repo-check",
  "-s",
  "read-only",
  "--config",
  'approval_policy="never"',
  PROMPT,
];

describe("tryGenerateWithCli Windows launch", () => {
  it("starts an npm-installed codex through cmd.exe", async () => {
    const binDir = path.join(root, "npm-bin");
    installNpmSiblings(binDir, "codex");
    const { execFile, calls } = recordingExecFile();

    const result = await tryGenerateWithCli(PROMPT, root, {
      platform: "win32",
      env: windowsEnv(binDir),
      execFile,
    });

    expect(result?.subject).toBe("Add Windows launch");
    expect(calls).toHaveLength(1);
    expect(calls[0]!.file).toBe("C:\\Windows\\System32\\cmd.exe");
    expect(calls[0]!.args).toEqual(expectedCmdArgs(path.join(binDir, "codex.cmd"), CODEX_ARGS));
    // No execFile `timeout`: it would kill only the cmd.exe wrapper, leaving
    // the shim's real CLI running. The wrapper's tree is torn down instead.
    expect(calls[0]!.options).toEqual({
      cwd: root,
      maxBuffer: 2 * 1024 * 1024,
      windowsVerbatimArguments: true,
    });
  });

  it("skips a candidate whose launch cannot happen and tries the next one", async () => {
    // codex exists only as npm's `.ps1`, which has no interpreter to run it;
    // claude is a proper npm install and answers.
    const codexDir = path.join(root, "codex-ps1-only");
    fs.mkdirSync(codexDir, { recursive: true });
    fs.writeFileSync(path.join(codexDir, "codex.ps1"), "# not launchable\n");
    const claudeDir = path.join(root, "claude-npm-bin");
    installNpmSiblings(claudeDir, "claude");
    const { execFile, calls } = recordingExecFile();

    const result = await tryGenerateWithCli(PROMPT, root, {
      platform: "win32",
      env: {
        ...windowsEnv(claudeDir),
        PATH: `${codexDir};${claudeDir}`,
      },
      execFile,
    });

    expect(result?.subject).toBe("Add Windows launch");
    expect(calls).toHaveLength(1);
    expect(calls[0]!.file).toBe("C:\\Windows\\System32\\cmd.exe");
    expect(calls[0]!.args).toEqual(
      expectedCmdArgs(path.join(claudeDir, "claude.cmd"), [
        "-p",
        PROMPT,
        "--dangerously-skip-permissions",
      ]),
    );
  });

  it("refuses to truncate a multi-line prompt through cmd.exe", async () => {
    // Every real commit prompt is multi-line (buildCommitPrompt joins it with
    // newlines), and cmd.exe ends the command at the first line break.
    // windowsLaunch refuses that argv rather than launching a truncated
    // prompt, so every `.cmd` candidate is skipped and the caller keeps the
    // deterministic suggestion. Passing the prompt on stdin would be the way
    // to support these shims — weakening the refusal is not.
    const binDir = path.join(root, "all-npm-bin");
    for (const name of ["codex", "claude", "opencode"]) installNpmSiblings(binDir, name);
    const { execFile, calls } = recordingExecFile();

    const result = await tryGenerateWithCli("Write a commit message\nfor the staged changes", root, {
      platform: "win32",
      env: windowsEnv(binDir),
      execFile,
    });

    expect(result).toBeNull();
    expect(calls).toEqual([]);
  });

  it("off Windows calls execFile exactly as before", async () => {
    const { execFile, calls } = recordingExecFile();

    const result = await tryGenerateWithCli(PROMPT, root, {
      platform: "linux",
      env: {},
      execFile,
    });

    expect(result?.subject).toBe("Add Windows launch");
    expect(calls).toHaveLength(1);
    expect(calls[0]!.file).toBe("codex");
    expect(calls[0]!.args).toEqual(CODEX_ARGS);
    // The same three option keys as the original call, and no launch key.
    expect(calls[0]!.options).toEqual({
      cwd: root,
      timeout: 25_000,
      maxBuffer: 2 * 1024 * 1024,
    });
  });
});
